#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────
# fcs-deploy-gate handoff: helpers for the stages below. The library above is
# the skill's template, untouched. Run from the repository root, inside the
# virtualenv that has the Gate installed (pip install -e '.[dev]'). Nothing
# here names the work environment: every host, organisation, group and path
# is asked for and kept in ENV_FILE (.env by default, gitignored, mode 0600).
# Client secrets are held in memory for the run and never written anywhere.
# ──────────────────────────────────────────────────────────────────────────

GATE_REPO_NAME="fcs-deploy-gate"

# gh_ready succeeds when gh is installed and logged in.
gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# set_org_secret NAME VALUE sets a GitHub organisation secret visible to the
# repositories in $GITHUB_SECRET_REPOS, via gh; otherwise it is listed to do by hand.
set_org_secret() {
  local name="$1" value="$2"
  say "Running: gh secret set $name --org $GITHUB_ORG --visibility selected --repos $GITHUB_SECRET_REPOS (value on stdin)"
  if gh_ready && printf '%s' "$value" | gh secret set "$name" --org "$GITHUB_ORG" \
      --visibility selected --repos "$GITHUB_SECRET_REPOS" >/dev/null; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s organisation secret %s on %s\n' "$GREEN" "$RESET" "$name" "$GITHUB_ORG"
    return
  fi
  SKIPPED+=("organisation secret $name on $GITHUB_ORG, selected repositories: $GITHUB_SECRET_REPOS")
  warn "could not set organisation secret $name with gh; add it by hand on the page that is open"
}

# record KEY "what" notes a confirmed manual step in ENV_FILE with the UTC date.
record() { write_env "$1" "$2, $(date -u +%Y-%m-%d)"; }

# console_host REGION prints the Falcon console host for a region, or fails.
console_host() {
  case "$1" in
    us-1) printf 'falcon.crowdstrike.com' ;;
    us-2) printf 'falcon.us-2.crowdstrike.com' ;;
    eu-1) printf 'falcon.eu-1.crowdstrike.com' ;;
    us-gov-1) printf 'falcon.laggar.gcw.crowdstrike.com' ;;
    us-gov-2) printf 'falcon.us-gov-2.crowdstrike.mil' ;;
    *) return 1 ;;
  esac
}

# ask_ci_secret reads the CI client secret, hidden, until something is entered. It is
# held in memory for the run and never written to ENV_FILE; later stages call this
# again and it returns at once while the value is held.
ask_ci_secret() {
  until [[ -n "${CI_CLIENT_SECRET:-}" ]]; do
    ask_secret CI_CLIENT_SECRET "Paste the CI client secret:"
  done
}

run_wizard() {

TOTAL_STAGES=15

banner "fcs-deploy-gate: handoff to the work environment"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: tools and names"
say "Run this from the root of your clone, inside the virtualenv that has the Gate"
say "installed (pip install -e '.[dev]'). It opens pages, shows every command before"
say "running it, and keeps what you confirm in $ENV_FILE."
[[ -f pyproject.toml && -d src/fcs_deploy_gate ]] || { warn "not at the repository root; cd there and re-run"; exit 1; }
PYTHON=$(command -v python || command -v python3) || { warn "no python on PATH"; exit 1; }
"$PYTHON" -c 'import pytest, fcs_deploy_gate' 2>/dev/null || warn "pytest or the Gate is not importable: pip install -e '.[dev]' (the pin and release stages need both)"
command -v fcs-deploy-gate >/dev/null 2>&1 || warn "fcs-deploy-gate is not on PATH: activate the virtualenv (the pin stage needs it)"
if gh_ready; then
  note "gh is authenticated: secrets, the access policy and the live run can be set from here"
else
  note "gh is missing or not logged in: those steps fall back to the browser"
fi
ask GITHUB_ORG "GitHub organisation the Gate moves to (the slug):"
until [[ "$GITHUB_ORG" =~ ^[A-Za-z0-9-]+$ ]]; do
  warn "an organisation slug is letters, digits and hyphens"
  ask GITHUB_ORG "GitHub organisation the Gate moves to (the slug):"
done
ask GITHUB_SECRET_REPOS "Repositories that may read the organisation secrets, comma-separated names without owner (include $GATE_REPO_NAME for the live check):"
ask GITLAB_URL "GitLab instance URL (https://...):"
GITLAB_URL="${GITLAB_URL%/}"
ask GITLAB_GROUP "GitLab group that owns the Consumer projects (full path):"
ask GITLAB_GATE_PROJECT "Path of the Gate project on GitLab (for example $GITLAB_GROUP/$GATE_REPO_NAME):"
until [[ "$GITLAB_GROUP" =~ ^[A-Za-z0-9._/-]+$ && "$GITLAB_GATE_PROJECT" =~ ^[A-Za-z0-9._/-]+$ ]]; do
  warn "GitLab paths are letters, digits, dots, underscores, hyphens and slashes"
  ask GITLAB_GROUP "GitLab group that owns the Consumer projects (full path):"
  ask GITLAB_GATE_PROJECT "Path of the Gate project on GitLab:"
done
ask FALCON_REGION "Falcon region (us-1, us-2, eu-1, us-gov-1, us-gov-2):"
until CONSOLE_HOST=$(console_host "$FALCON_REGION"); do
  warn "unknown region $FALCON_REGION"
  ask FALCON_REGION "Falcon region (us-1, us-2, eu-1, us-gov-1, us-gov-2):"
done
write_env GITHUB_ORG "$GITHUB_ORG"
write_env GITHUB_SECRET_REPOS "$GITHUB_SECRET_REPOS"
write_env GITLAB_URL "$GITLAB_URL"
write_env GITLAB_GROUP "$GITLAB_GROUP"
write_env GITLAB_GATE_PROJECT "$GITLAB_GATE_PROJECT"
write_env FALCON_REGION "$FALCON_REGION"
TARGET="$GITHUB_ORG/$GATE_REPO_NAME"
note "Falcon console for $FALCON_REGION: https://$CONSOLE_HOST"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub: migrate the repository and its one reference"
CURRENT=$(sed -nE 's#^[[:space:]]*uses: ([^/[:space:]]+/[^/[:space:]]+)/\.github/actions/gate@.*#\1#p' .github/workflows/gate.yml | head -n1)
say "The repository's owner and name appear in one place in code: the uses: line of"
say ".github/workflows/gate.yml (now $CURRENT), echoed by the README example and held"
say "by the tests. Everything else is relative."
open_url "https://github.com/organizations/$GITHUB_ORG/repositories/new"
step "Create the empty repository $TARGET (private is fine: Consumers reach it through the access policy, not visibility)."
step "Then: git remote add work git@github.com:$TARGET.git && git push work main"
pause "Pushed? Press Enter."
if [[ "$CURRENT" == "$TARGET" ]]; then
  note "the reference already reads $TARGET; nothing to replace"
else
  # The issue-tracker pointers in AGENTS.md and docs/agents are not the adapter's
  # reference: they change only if the issues move, and are listed below to judge.
  mapfile -t FILES < <(git grep -l -F "$CURRENT" -- . ':!AGENTS.md' ':!docs/agents' || true)
  ESCAPED=$(printf '%s' "$CURRENT" | sed 's/[][\.*^$#&]/\\&/g')
  say "Files that carry $CURRENT:"
  for f in "${FILES[@]}"; do note "  $f"; done
  if confirm "Replace $CURRENT with $TARGET in these files?"; then
    for f in "${FILES[@]}"; do sed -i "s#$ESCAPED#$TARGET#g" "$f"; done
    if "$PYTHON" -m pytest -q tests/test_github_adapter.py tests/test_gitlab_adapter.py; then
      note "the adapter tests pass with the new reference"
    else
      warn "the adapter tests fail: fix before committing"
    fi
    step "Commit the change (\"Point the adapter at $TARGET\") and push it."
    pause
  fi
fi
LEFT=$(git grep -n -F "${CURRENT%%/*}" || true)
if [[ -n "$LEFT" ]]; then
  say "Other mentions of the old owner, for you to judge (the issue-tracker pointers in"
  say "AGENTS.md and docs/agents move only if the issues move):"
  printf '%s\n' "$LEFT" | sed 's/^/    /'
  pause
fi
record MIGRATED_GITHUB "pushed to $TARGET"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitLab: the Gate project, a mirror of GitHub"
say "GitHub is canonical. The GitLab instance holds the Gate as a pull mirror if it can"
say "reach GitHub; otherwise every release is pushed to both remotes."
open_url "$GITLAB_URL/projects/new"
step "Create the project at $GITLAB_GATE_PROJECT (blank, no README)."
open_url "$GITLAB_URL/$GITLAB_GATE_PROJECT/-/settings/repository"
step "Mirroring repositories: direction Pull from https://github.com/$TARGET.git with a GitHub token that can read it."
step "If the instance cannot reach GitHub: git remote add gitlab $GITLAB_URL/$GITLAB_GATE_PROJECT.git, and push main and every tag there as well."
if confirm "Pull mirror configured and its first update succeeded?"; then
  write_env GITLAB_MIRROR "pull"
else
  write_env GITLAB_MIRROR "push"
  note "recorded as a push mirror: the release stage will remind you to push the tag to both remotes"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Falcon: the CI client"
say "The client the Gate runs as. Two scopes and nothing else, so a leaked pipeline"
say "secret can download the CLI and scan, not read the tenant's IOMs or assets."
open_url "https://$CONSOLE_HOST/"
step "Support and resources, API clients and keys (or search for it in the console)."
step "Create (or Add new) API client. Name: fcs-deploy-gate-ci. Description: CI client of the Gate."
step "Scopes: Cloud Security Tools Download: Read. Infrastructure as Code: Read and Write."
step "Create, then copy the client id and the secret: the secret is shown once. Keep both"
step "in the team password manager too; the GitLab variables are pasted by hand later."
ask CI_CLIENT_ID "Paste the CI client id:"
until [[ -n "$CI_CLIENT_ID" ]]; do ask CI_CLIENT_ID "Paste the CI client id:"; done
ask_ci_secret
write_env CI_CLIENT_ID "$CI_CLIENT_ID"
note "the secret stays in memory for this run and is never written to $ENV_FILE"
if confirm "Does the client show exactly those two scopes?"; then
  record CI_CLIENT "created with the two scopes"
else
  warn "fix the scopes before going on"
  record CI_CLIENT "scopes not confirmed"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Falcon: the mapping client (laptop only)"
say "Read-only, used from a laptop for the IOM mapping measurement (ADR 0005), never in CI."
step "Same page. Create API client. Name: fcs-deploy-gate-mapping."
step "Scopes, all Read only: CSPM registration; Cloud Security Policies;"
step "Cloud Security API Detections; Cloud Security API Assets."
warn "Leave CSPM registration Write unticked: it also governs cloud account registration."
step "Keep its secret in the password manager. This wizard does not take it."
ask MAPPING_CLIENT_ID "Paste the mapping client id:"
write_env MAPPING_CLIENT_ID "$MAPPING_CLIENT_ID"
if confirm "Four Read scopes, and CSPM registration Write unticked?"; then
  record MAPPING_CLIENT "created read-only"
else
  warn "fix the scopes before going on"
  record MAPPING_CLIENT "scopes not confirmed"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub organisation secrets"
say "FALCON_CLIENT_ID and FALCON_CLIENT_SECRET as organisation secrets, visible to the"
say "selected repositories only: $GITHUB_SECRET_REPOS."
ask_ci_secret
open_url "https://github.com/organizations/$GITHUB_ORG/settings/secrets/actions"
set_org_secret FALCON_CLIENT_ID "$CI_CLIENT_ID"
set_org_secret FALCON_CLIENT_SECRET "$CI_CLIENT_SECRET"
step "If either was skipped: New organisation secret, the name above, repository access"
step "\"Selected repositories\", pick $GITHUB_SECRET_REPOS."
if confirm "Both secrets present with selected-repository access?"; then
  record GITHUB_ORG_SECRETS "placed"
else
  record GITHUB_ORG_SECRETS "not confirmed"
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GitLab group variables"
say "The same two values as CI/CD variables on the group $GITLAB_GROUP, masked. Unprotected"
say "if the Gate is to run in merge-request pipelines (they run on unprotected branches):"
say "the group's membership is then the trust boundary for the CI client, which is why it"
say "holds only the two scopes. A stricter estate keeps them protected and runs the Gate"
say "only in default-branch pipelines, giving up the merge-request block."
open_url "$GITLAB_URL/groups/$GITLAB_GROUP/-/settings/ci_cd"
step "Variables, Add variable: key FALCON_CLIENT_ID, value $CI_CLIENT_ID, Masked, not Protected."
step "Add variable: key FALCON_CLIENT_SECRET, the secret from the password manager, Masked and hidden, not Protected."
if confirm "Both variables added, masked?"; then
  if confirm "Unprotected, so merge-request pipelines run the Gate?"; then
    record GITLAB_GROUP_VARIABLES "masked, unprotected"
  else
    record GITLAB_GROUP_VARIABLES "masked, protected: default-branch pipelines only"
  fi
else
  record GITLAB_GROUP_VARIABLES "not confirmed"
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the repository access policy"
say "A reusable workflow and a composite action in a private repository are callable from"
say "the organisation's other repositories only when the repository says so."
open_url "https://github.com/$TARGET/settings/actions"
say "Running: gh api -X PUT repos/$TARGET/actions/permissions/access -f access_level=organization"
if gh_ready && gh api -X PUT "repos/$TARGET/actions/permissions/access" -f access_level=organization >/dev/null; then
  printf '  %s✓ set%s access level: organization\n' "$GREEN" "$RESET"
else
  step "Access: \"Accessible from repositories in the organization\", Save."
fi
open_url "https://github.com/organizations/$GITHUB_ORG/settings/actions"
step "On the organisation's Actions policy, check that actions/checkout, actions/setup-python"
step "and actions/upload-artifact are allowed (the action pins them by commit)."
if confirm "Access policy set and the three actions allowed?"; then
  record GITHUB_ACCESS_POLICY "organization"
else
  record GITHUB_ACCESS_POLICY "not confirmed"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "GitLab: job token permissions, image mirror, instance variables"
say "Consumer jobs clone the Gate project with their CI_JOB_TOKEN, run on a mirrored Python"
say "image, and read the Gate's path and image from variables set once."
open_url "$GITLAB_URL/$GITLAB_GATE_PROJECT/-/settings/ci_cd"
step "Job token permissions: Add group or project, $GITLAB_GROUP. Users who trigger Consumer pipelines also need read access to the Gate project."
step "Mirror python:3.12 (the full image: the job needs git) into the internal registry."
ask FCS_GATE_IMAGE "Image reference the jobs will pull (for example \$CI_REGISTRY/mirror/python:3.12):"
write_env FCS_GATE_IMAGE "$FCS_GATE_IMAGE"
step "On the group ($GITLAB_URL/groups/$GITLAB_GROUP/-/settings/ci_cd) or the instance, add"
step "FCS_GATE_IMAGE = $FCS_GATE_IMAGE and FCS_GATE_PROJECT = $GITLAB_GATE_PROJECT."
step "Runners need egress to the Falcon API host, the pre-signed download host and PyPI (or PIP_INDEX_URL)."
if confirm "Job token permissions, image and the two variables in place?"; then
  record GITLAB_INSTANCE_SETUP "job token permissions, image, variables"
else
  record GITLAB_INSTANCE_SETUP "not confirmed"
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Fill the checksum pin"
say "The Gate refuses to download the CLI while the pin's SHA-256 is empty. The pin"
say "command asks the download API for the pinned version and prints what it publishes."
ask_ci_secret
command -v fcs-deploy-gate >/dev/null 2>&1 || { warn "fcs-deploy-gate is not on PATH; activate the virtualenv and re-run"; exit 1; }
note "Proxies are honoured from HTTPS_PROXY and NO_PROXY in this shell."
say "Running: fcs-deploy-gate pin --region $FALCON_REGION (credentials in its environment only)"
PIN_OUTPUT=$(FALCON_CLIENT_ID="$CI_CLIENT_ID" FALCON_CLIENT_SECRET="$CI_CLIENT_SECRET" fcs-deploy-gate pin --region "$FALCON_REGION") || { warn "the pin command failed (its message is above): egress, credentials or scopes"; exit 1; }
printf '%s\n' "$PIN_OUTPUT" | sed 's/^/    /'
PIN_VERSION=$(printf '%s\n' "$PIN_OUTPUT" | sed -n 's/^version=//p')
PIN_SHA256=$(printf '%s\n' "$PIN_OUTPUT" | sed -n 's/^sha256=//p')
[[ "$PIN_VERSION" =~ ^[0-9][0-9A-Za-z.+-]*$ && "$PIN_SHA256" =~ ^[0-9a-f]{64}$ ]] || { warn "unexpected pin output"; exit 1; }
if confirm "Write version $PIN_VERSION and this SHA-256 into src/fcs_deploy_gate/download.py?"; then
  sed -i -E "s|^PIN = CliPin\(version=\"[^\"]*\", sha256=\"[^\"]*\"\)|PIN = CliPin(version=\"$PIN_VERSION\", sha256=\"$PIN_SHA256\")|" src/fcs_deploy_gate/download.py
  grep -q "sha256=\"$PIN_SHA256\"" src/fcs_deploy_gate/download.py || warn "the PIN line was not found; edit it by hand"
  git --no-pager diff --stat -- src/fcs_deploy_gate/download.py
  if "$PYTHON" -m pytest -q; then
    note "the suite passes with the filled pin"
  else
    warn "the suite fails: look before committing"
  fi
  write_env PIN_VERSION "$PIN_VERSION"
  write_env PIN_SHA256 "$PIN_SHA256"
  step "Commit on a branch and open a pull request, \"Pin fcs CLI $PIN_VERSION\", with a note on"
  step "rule and severity changes since the previous pin (none for the first). Merge it."
  pause "Merged? Press Enter."
  record PIN_FILLED "$PIN_VERSION"
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Release: an immutable tag"
say "A release is the package version in pyproject.toml, both adapter references at the"
say "same version, one commit, one tag that is never moved (README, \"Release procedure\")."
RELEASE_VERSION=$("$PYTHON" -c 'import tomllib; print(tomllib.load(open("pyproject.toml", "rb"))["project"]["version"])')
if "$PYTHON" -m pytest -q tests/test_github_adapter.py tests/test_gitlab_adapter.py; then
  note "the adapter references agree with version $RELEASE_VERSION"
else
  warn "the adapter references and the package version disagree: fix by pull request first"
  exit 1
fi
RELEASE_TAG="v$RELEASE_VERSION"
ask GIT_REMOTE "Git remote that points at github.com/$TARGET:"
until git remote get-url "$GIT_REMOTE" >/dev/null 2>&1; do
  warn "no remote named $GIT_REMOTE"
  ask GIT_REMOTE "Git remote that points at github.com/$TARGET:"
done
write_env GIT_REMOTE "$GIT_REMOTE"
say "Running: git fetch --tags $GIT_REMOTE"
git fetch --quiet --tags "$GIT_REMOTE" || warn "the fetch failed; going on with local refs"
if git rev-parse -q --verify "refs/tags/$RELEASE_TAG" >/dev/null; then
  note "$RELEASE_TAG already exists; tags are never moved, so nothing is tagged"
elif ! git merge-base --is-ancestor HEAD "refs/remotes/$GIT_REMOTE/main" 2>/dev/null; then
  warn "HEAD ($(git rev-parse --short HEAD)) is not on $GIT_REMOTE/main; check out the merged pin commit and re-run"
else
  say "HEAD is $(git rev-parse --short HEAD), on $GIT_REMOTE/main."
  say "On yes: git tag -a $RELEASE_TAG -m \"fcs-deploy-gate $RELEASE_TAG\" && git push $GIT_REMOTE $RELEASE_TAG"
  if confirm "Tag $RELEASE_TAG here and push it to $GIT_REMOTE? (a tag is never moved afterwards)"; then
    git tag -a "$RELEASE_TAG" -m "fcs-deploy-gate $RELEASE_TAG"
    git push "$GIT_REMOTE" "$RELEASE_TAG"
  fi
fi
if git rev-parse -q --verify "refs/tags/$RELEASE_TAG" >/dev/null; then
  if [[ "$GITLAB_MIRROR" == "push" ]]; then
    step "Push main and $RELEASE_TAG to the GitLab remote as well."
  else
    step "Let the pull mirror update (Settings, Repository, Mirroring repositories, Update now) so $GITLAB_GATE_PROJECT has $RELEASE_TAG."
  fi
  write_env RELEASE_TAG "$RELEASE_TAG"
else
  warn "there is no $RELEASE_TAG yet; the live runs below need it"
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "First Advisory run on GitHub"
say "The Live check workflow calls the reusable workflow against the insecure fixture in"
say "Advisory mode: the job succeeds and the summary shows what the Gate would block."
open_url "https://github.com/$TARGET/actions/workflows/live-check.yml"
say "On yes: gh workflow run live-check.yml -R $TARGET -f region=$FALCON_REGION -f mode=advisory"
if gh_ready && confirm "Start it from here with gh?"; then
  if gh workflow run live-check.yml -R "$TARGET" -f "region=$FALCON_REGION" -f mode=advisory; then
    note "started; it appears on the page in a moment"
  else
    warn "gh could not start it; use Run workflow on the page"
  fi
else
  step "Run workflow: region $FALCON_REGION, mode advisory."
fi
step "Open the run. The job summary should lead with a blocked Verdict (Advisory) and list"
step "the fixture's public-bucket Finding; the artifact holds verdict.json, summary.md and the raw report."
step "A scan error instead names its cause: egress to the API host or the download URL, the"
step "token with upload (fallback: the CLI's own credential variables), or the upload flag's spelling. Issue #9 records the fix."
ask GITHUB_LIVE_RUN_URL "Paste the run's URL:"
write_env GITHUB_LIVE_RUN_URL "$GITHUB_LIVE_RUN_URL"
if confirm "Did the summary list the public-bucket Finding?"; then
  record GITHUB_LIVE_RUN "public-bucket Finding reported"
else
  record GITHUB_LIVE_RUN "did not report the Finding: see the run"
fi

# ── 13 ────────────────────────────────────────────────────────────────────
stage "First Advisory run on GitLab"
say "The Gate project's own .gitlab-ci.yml includes the template and scans the fixture in"
say "Advisory mode; it runs from the web form only."
open_url "$GITLAB_URL/$GITLAB_GATE_PROJECT/-/pipelines/new"
step "Branch: the default branch. Variable FCS_GATE_REGION = $FALCON_REGION (and FCS_GATE_IMAGE"
step "if the group variable is not set yet). Run pipeline."
step "The fcs-deploy-gate job log ends with the summary; artifacts are under fcs-gate/."
step "Also run CI Lint (CI/CD, Pipeline editor, Validate) on a Consumer pipeline that includes"
step "the template at $RELEASE_TAG from $GITLAB_GATE_PROJECT: that check cannot run outside the instance."
ask GITLAB_LIVE_PIPELINE_URL "Paste the pipeline's URL:"
write_env GITLAB_LIVE_PIPELINE_URL "$GITLAB_LIVE_PIPELINE_URL"
if confirm "Did the summary list the public-bucket Finding, and did CI Lint pass?"; then
  record GITLAB_LIVE_RUN "public-bucket Finding reported, CI Lint clean"
else
  record GITLAB_LIVE_RUN "see the pipeline"
fi

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Capture the real report"
say "The fixture reports were reconstructed from CrowdStrike's editor plugins and are"
say "provisional until one sanitised real report replaces them (issue #9)."
step "From either run's artifact, save fcs-report.json outside the repository."
step "Compare its stats block with what verdict.json recorded under cloud_rules_evidence:"
step "the field names the Gate reads (stats.rule_stats.rules_enabled) are provisional too."
step "Sanitise before it enters the repository: scan_uuid, path, repository details, any"
step "account id or host name; keep the structure, severities and rule UUIDs."
ask REAL_REPORT_PATH "Local path of the raw report (kept out of git):"
write_env REAL_REPORT_PATH "$REAL_REPORT_PATH"
if confirm "Saved outside the repository, with nothing from it committed yet?"; then
  record REAL_REPORT "captured"
else
  record REAL_REPORT "not confirmed"
fi

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Confirm the console upload"
say "Each run uploads the unfiltered scan under its project name: $TARGET from GitHub"
say "and $GITLAB_GATE_PROJECT from GitLab."
open_url "https://$CONSOLE_HOST/"
step "Cloud security, Infrastructure as code: the view that lists IaC scans or projects. No"
step "public document names the exact menu, so note the path you used."
ask CONSOLE_IAC_MENU "Menu path where the uploaded scans appeared:"
write_env CONSOLE_IAC_MENU "$CONSOLE_IAC_MENU"
if confirm "Are both scans visible under their project names?"; then
  record CONSOLE_UPLOAD "both visible"
else
  record CONSOLE_UPLOAD "not found: see issue #9"
fi

finish
}

run_wizard "$@"; exit
